import "server-only";
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import { cache } from "react";
import { parse as parseYaml } from "yaml";
import { z } from "zod";
import { GalleryAlbumFile, GalleryCategory, GalleryManifest } from "./schema";
import galleryCategories from "./sources/local/gallery-categories.json";
import { showDrafts } from "./markdown-collection";

/**
 * Gallery albums: src/content/sources/local/gallery/<album-slug>/
 *   album.yaml   — title, date, city, description, photos (alt text, captions)
 *   photos.json  — generated by `npm run gallery` (sizes, placeholders)
 * Processed images live in public/gallery/<album-slug>/.
 */
const DIR = path.join(process.cwd(), "src/content/sources/local/gallery");
const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

export interface GalleryPhoto {
  id: string;
  albumSlug: string;
  width: number;
  height: number;
  alt: string;
  caption?: string;
  /** Largest version. */
  src: string;
  srcSet: string;
  blur: string;
}

export const GALLERY_CATEGORIES = z.array(GalleryCategory).parse(galleryCategories);

export interface GalleryAlbum {
  slug: string;
  title: string;
  date: string;
  category?: string;
  city?: string;
  description?: string;
  cover: GalleryPhoto;
  photos: GalleryPhoto[];
}

export const loadGallery = cache(async (): Promise<GalleryAlbum[]> => {
  let slugs: string[] = [];
  try {
    slugs = (await readdir(DIR, { withFileTypes: true })).filter((d) => d.isDirectory()).map((d) => d.name);
  } catch {
    return [];
  }
  const albums: GalleryAlbum[] = [];
  for (const slug of slugs) {
    if (!SLUG.test(slug)) throw new Error(`Gallery album folder "${slug}": use lowercase letters, numbers and hyphens.`);
    const where = `gallery/${slug}/album.yaml`;
    let raw: string;
    try {
      raw = await readFile(path.join(DIR, slug, "album.yaml"), "utf8");
    } catch {
      throw new Error(`Gallery album "${slug}" has no album.yaml.`);
    }
    const parsed = GalleryAlbumFile.safeParse(parseYaml(raw));
    if (!parsed.success) throw new Error(`Invalid ${where}:\n${z.prettifyError(parsed.error)}`);
    const album = parsed.data;
    if (album.category && !GALLERY_CATEGORIES.some((c) => c.id === album.category))
      throw new Error(`${where}: unknown category "${album.category}". Use one of: ${GALLERY_CATEGORIES.map((c) => c.id).join(", ")}.`);
    if (album.draft && !showDrafts()) continue;
    if (album.photos.length === 0) continue;

    let manifest: GalleryManifest = {};
    try {
      manifest = GalleryManifest.parse(JSON.parse(await readFile(path.join(DIR, slug, "photos.json"), "utf8")));
    } catch {
      throw new Error(`Gallery album "${slug}" has no valid photos.json. Run \`npm run gallery\`.`);
    }

    const photos: GalleryPhoto[] = album.photos.map((p) => {
      const m = manifest[p.file];
      if (!m) throw new Error(`${where}: photo "${p.file}" has not been processed. Run \`npm run gallery\`.`);
      const url = (w: number) => `/gallery/${slug}/${m.id}-${w}.webp`;
      return {
        id: m.id,
        albumSlug: slug,
        width: m.width,
        height: m.height,
        alt: p.alt,
        caption: p.caption,
        src: url(m.widths[m.widths.length - 1]),
        srcSet: m.widths.map((w) => `${url(w)} ${w}w`).join(", "),
        blur: m.blur,
      };
    });
    const cover = (album.cover && photos[album.photos.findIndex((p) => p.file === album.cover)]) || photos[0];
    if (album.cover && !album.photos.some((p) => p.file === album.cover)) throw new Error(`${where}: cover "${album.cover}" is not one of the album's photos.`);
    albums.push({ slug, title: album.title, date: album.date, category: album.category, city: album.city, description: album.description, cover, photos });
  }
  return albums.sort((a, b) => b.date.localeCompare(a.date) || a.title.localeCompare(b.title));
});
